package com.example.demodatn.service.hotro;
import com.icegreen.greenmail.util.*;
import com.example.demodatn.service.nhanvien.AccountMailService;
import com.example.demodatn.dto.hotro.SupportChatRequest;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.context.DynamicPropertySource;
import org.springframework.test.util.ReflectionTestUtils;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest
class SupportChatMailIntegrationTest {
 static GreenMail smtp=new GreenMail(new ServerSetup(0,"127.0.0.1",ServerSetup.PROTOCOL_SMTP));static{smtp.start();}
 @DynamicPropertySource static void mail(DynamicPropertyRegistry r){r.add("spring.mail.host",()->"127.0.0.1");r.add("spring.mail.port",()->smtp.getSmtp().getPort());r.add("spring.mail.username",()->"");r.add("spring.mail.password",()->"");r.add("spring.mail.properties.mail.smtp.auth",()->false);r.add("spring.mail.properties.mail.smtp.starttls.enable",()->false);r.add("spring.mail.properties.mail.smtp.connectiontimeout",()->500);r.add("spring.mail.properties.mail.smtp.timeout",()->500);r.add("shop.mail.from",()->"store@example.test");}
 @Autowired SupportChatService chat;@Autowired SupportChatMailNotifier notifier;@Autowired AccountMailService mail;@Autowired JdbcTemplate jdbc;
 long id;SupportChatService.Actor guest;SupportChatService.Actor admin=new SupportChatService.Actor("admin",null);
 @BeforeEach void setup(){com.example.demodatn.TestDatabaseGuard.check(jdbc);smtp.setUser("gd29-mail@example.test","fixture","fixture");guest=new SupportChatService.Actor(null,SupportChatService.hashToken(SupportChatService.newToken()));id=chat.open(guest,"Nguyễn Văn Ánh","gd29-mail@example.test","mail-test").id();jdbc.update("UPDATE chat_hoi_thoai SET created_at=DATEADD(MINUTE,-3,SYSDATETIME()),last_customer_seen_at=DATEADD(MINUTE,-3,SYSDATETIME()) WHERE id=?",id);}
 void send(String text){chat.send(id,new SupportChatRequest(UUID.randomUUID().toString(),"VAN_BAN",text,null,null),null,admin,"mail-test",null);}
 @Test void offlineOneEscapedMailAndCooldown()throws Exception{int before=smtp.getReceivedMessages().length;send("Xin chào Nguyễn Văn Ánh <script>không chạy</script>");assertTrue(smtp.waitForIncomingEmail(8000,before+1),"GreenMail received message");for(int n=0;n<40&&jdbc.queryForObject("SELECT COUNT(*) FROM chat_mail_log WHERE hoi_thoai_id=? AND trang_thai=N'SENT'",Integer.class,id)==0;n++)Thread.sleep(50);assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM chat_mail_log WHERE hoi_thoai_id=? AND trang_thai=N'SENT'",Integer.class,id));var message=smtp.getReceivedMessages()[before];var parts=new java.util.ArrayList<String>();collect(message,parts);String decoded=String.join("\n",parts);assertTrue(decoded.contains("Nguyễn Văn Ánh")&&decoded.contains("support=open"),"Decoded text keeps Vietnamese and store link");assertTrue(decoded.contains("&lt;script&gt;")&&decoded.contains("&lt;/script&gt;"),"HTML fragment is escaped");System.out.println("GD29_MAIL_TO=gd29-mail@example.test SUBJECT="+message.getSubject()+" BODY="+decoded);send("Tin tiếp theo trong ba mươi phút");Thread.sleep(500);assertEquals(before+1,smtp.getReceivedMessages().length);assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM chat_mail_log WHERE hoi_thoai_id=?",Integer.class,id));}
 @Test void onlineNoEmailAndMissingConfigurationDoesNotBreakMessages()throws Exception{int before=smtp.getReceivedMessages().length;chat.socketConnected("gd29-online-fixture",guest);try{send("Tin khi khách online");Thread.sleep(300);assertEquals(before,smtp.getReceivedMessages().length);}finally{chat.socketDisconnected("gd29-online-fixture");}String previous=mail.getResolvedHost();ReflectionTestUtils.setField(mail,"host","");try{send("Chưa cấu hình mail vẫn gửi tin");Thread.sleep(200);assertEquals(before,smtp.getReceivedMessages().length);}finally{ReflectionTestUtils.setField(mail,"host",previous);}assertEquals(2,jdbc.queryForObject("SELECT COUNT(*) FROM chat_tin_nhan WHERE hoi_thoai_id=? AND nguoi_gui_loai=N'NHAN_VIEN'",Integer.class,id));var phone=new SupportChatService.Actor(null,SupportChatService.hashToken(SupportChatService.newToken()));id=chat.open(phone,"Khách không có email","0912932999","mail-test").id();jdbc.update("UPDATE chat_hoi_thoai SET created_at=DATEADD(MINUTE,-3,SYSDATETIME()) WHERE id=?",id);send("Khách không email vẫn nhận được tin");Thread.sleep(500);assertEquals(before,smtp.getReceivedMessages().length);assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM chat_mail_log WHERE hoi_thoai_id=?",Integer.class,id));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM chat_tin_nhan WHERE hoi_thoai_id=?",Integer.class,id));}
 static void collect(jakarta.mail.Part part,java.util.List<String> text)throws Exception{Object content=part.getContent();if(content instanceof jakarta.mail.Multipart multi){for(int i=0;i<multi.getCount();i++)collect(multi.getBodyPart(i),text);}else if(content instanceof String value)text.add(value);}
 @Test void smtpFailureKeepsMessageAndRecordsFailure()throws Exception{int port=smtp.getSmtp().getPort();smtp.stop();try{send("SMTP tắt nhưng tin vẫn được lưu");for(int n=0;n<100&&jdbc.queryForObject("SELECT COUNT(*) FROM chat_mail_log WHERE hoi_thoai_id=? AND trang_thai=N'FAILED'",Integer.class,id)==0;n++)Thread.sleep(50);assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM chat_mail_log WHERE hoi_thoai_id=? AND trang_thai=N'FAILED'",Integer.class,id));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM chat_tin_nhan WHERE hoi_thoai_id=?",Integer.class,id));}finally{smtp=new GreenMail(new ServerSetup(port,"127.0.0.1",ServerSetup.PROTOCOL_SMTP));smtp.start();}}
 @AfterAll static void stop(){smtp.stop();}
}
